questions.question:
What is wrong with the following C++ code, and what problem can occur when the program ends?

class Data {
public:
    int* value;

    Data(int v) {
        value = new int(v);
    }

    ~Data() {
        delete value;
    }
};

int main() {
    Data a(10);
    Data b = a;
    cout << *a.value << " " << *b.value << endl;
    return 0;
}

What will the following code print?

int arr[3] = {10, 20, 30};
cout << arr[3] << endl;

What is wrong with the following code, and what will it print?

int* getValue() {
    int x = 10;
    return &x;
}

int main() {
    int* ptr = getValue();
    cout << *ptr << endl;
    return 0;
}

What is the time complexity of this code? 

for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j *= 2) {
        cout << i << " " << j << endl;
    }
}

What is the time complexity of the following function?

int mystery(int n) {
    if (n <= 1) return 1;
    return mystery(n / 2) + mystery(n / 2);
}

Consider this C++ function that computes the 50th Fibonacci number using a 32-bit signed int accumulator, letting arithmetic overflow wrap silently (as commonly observed on x86-64 with GCC):

int fib(int n) {
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    std::cout << fib(50) << std::endl;
}

What exact integer value does this program print? Do not report the mathematically correct Fibonacci(50) -- account for 32-bit signed integer overflow.

